/** Board03 alarm tone selection. Existing editor owns the unsaved Alarm draft. */
final class AlarmToneScreen implements AutoCloseable {
    interface WaveSource {Map<String,ToneWaveform> load(Context source)throws IOException;}
    static WaveSource waveSource=source->{Map<String,ToneWaveform> result=new HashMap<>();for(String tone:List.of("daybreak","pulse","chime"))try(InputStream in=source.getAssets().open(AlarmTones.asset(tone))){result.put(tone,ToneWaveform.read(in));}catch(IOException unavailable){/* Missing audio has no invented waveform. */}return result;};
    private static final class WaveHost {final String tone;final FrameLayout view;WaveHost(String tone,FrameLayout view){this.tone=tone;this.view=view;}}
    private final List<WaveHost> waveHosts=new ArrayList<>();
    private String settingsScope="";
    private final Activity activity;private final Context app;private final Records.Factory records;private final SharedPreferences soundPreferences;private final Alarm alarm;private final Runnable render,back,gentle,modes;private final AlarmTonePreview preview;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private final Map<String,ToneWaveform> waves=new HashMap<>();private final List<PlayButton> buttons=new ArrayList<>();private int tab,importGeneration;private String importError="",importName="My audio";private boolean closed,importing,paused=true,assetsLoaded;private CancellationSignal importingCancel;private Runnable importTimeout;private Button panelPlay,stop;private TextView previewValue,previewError;private Dialog dialog;
    private final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){preview.stop();}};
    AlarmToneScreen(Activity activity,Alarm alarm,Bundle saved,Runnable render,Runnable back,Runnable gentle){this(activity,alarm,saved,render,back,gentle,null);}
    AlarmToneScreen(Activity activity,Alarm alarm,Bundle saved,Runnable render,Runnable back,Runnable gentle,Runnable modes){this.activity=activity;app=activity.getApplicationContext();records=Records.factory;soundPreferences=SoundPreferences.factory.open(app);this.alarm=alarm;importName=alarm.toneDisplayName.isEmpty()?"My audio":alarm.toneDisplayName;this.render=render;this.back=back;this.gentle=gentle;this.modes=modes;preview=new AlarmTonePreview(AlarmToneAudio.provider.create(app),this::update);tab=alarm.tone.startsWith("content:")||alarm.tone.equals("system")?1:0;if(saved!=null){tab=saved.getInt("tab",tab);importError=saved.getString("error","");importName=saved.getString("name",importName);preview.volume(saved.getInt("previewVolume",25));}androidx.core.content.ContextCompat.registerReceiver(activity,noisy,new IntentFilter(AudioManagerAction.NOISY),androidx.core.content.ContextCompat.RECEIVER_NOT_EXPORTED);paused=!activity.hasWindowFocus();preview.visible(!paused);loadWaves();}
    private static final class AudioManagerAction {static final String NOISY=android.media.AudioManager.ACTION_AUDIO_BECOMING_NOISY;}
    Bundle save(){Bundle out=new Bundle();out.putInt("tab",tab);out.putInt("previewVolume",preview.volume());out.putString("error",importing?"Import was interrupted. Choose the file again.":importError);out.putString("name",importName);return out;}
    private void loadWaves(){Context source=app;WaveSource loader=waveSource;worker.execute(()->{Map<String,ToneWaveform> loaded;try{loaded=loader.load(source);}catch(IOException|RuntimeException unavailable){loaded=Map.of();}Map<String,ToneWaveform> result=loaded;main.post(()->{if(!closed){waves.putAll(result);assetsLoaded=true;for(WaveHost host:waveHosts)updateWave(host);}});});}
    private void updateWave(WaveHost host){ToneWaveform wave=waves.get(host.tone);if(wave==null)return;host.view.removeAllViews();int color=host.tone.equals("daybreak")?0xffc78956:host.tone.equals("pulse")?0xffa586d8:0xffc2a7e6;host.view.addView(new ClipWaveView(activity,wave.peaks,color,color),new FrameLayout.LayoutParams(-1,-1));}
    void render(LinearLayout body){waveHosts.clear();buttons.clear();panelPlay=null;stop=null;previewError=null;previewValue=null;body.setPadding(body.getPaddingLeft(),Design.dp(activity,8),body.getPaddingRight(),Design.dp(activity,8));RecordUi.label(activity,body);RecordUi.headerAction(RecordUi.header(body,"Alarm sound",back),"more","Alarm sound options",this::options);Design.space(body,8);if(alarm.soundMode.radio()){radio(body);return;}toneTabs(body);Design.space(body,6);if(alarm.soundModeInvalid||!alarm.soundMode.equals(AlarmSoundMode.SINGLE)){Design.item(body,"sound","Sound playback",alarm.soundModeInvalid?"Needs review":alarm.soundMode.title(),modes);Design.text(body,alarm.soundModeInvalid?"Review playback settings before saving.":alarm.soundMode.silent()?"Sound stays off in Silent mode. Samples below do not change this mode.":"Samples below preview one selected tone. Playlist order is set in Sound playback.",12,400,Design.MUTED);Design.space(body,8);}
        if(tab==0)for(String tone:List.of("daybreak","pulse","chime")){tone(body,tone);Design.line(body);}else{if(alarm.tone.startsWith("content:")){tone(body,alarm.tone);Design.line(body);}tone(body,"system");Design.line(body);if(!alarm.tone.startsWith("content:")){Design.space(body,8);Design.text(body,"Import an audio file to use it as your alarm.",13,400,Design.MUTED);}}
        LinearLayout importRow=Design.item(body,"file",importing?"Checking audio…":"Import audio file",null,importing?null:this::importAudio);importRow.setMinimumHeight(Design.dp(activity,64));RecordUi.enabled(importRow,!importing);Design.line(body);if(!importError.isEmpty()){Design.space(body,8);Design.text(body,importError,13,500,0xffa93919);}Design.space(body,12);slider(body,"Alarm volume",alarm.volume,10,100,value->alarm.volume=value,false);Design.space(body,10);
        LinearLayout panel=Design.col(activity);Design.pad(panel,18,12);panel.setBackground(Design.shape(activity,Design.SOFT,18));TextView selectedName=Design.text(panel,toneLabel(alarm.tone),18,600,Design.INK);selectedName.setMaxLines(2);selectedName.setEllipsize(android.text.TextUtils.TruncateAt.END);selectedName.setTooltipText(toneLabel(alarm.tone));Design.space(panel,6);slider(panel,"Preview volume",preview.volume(),0,25,preview::volume,true);
        LinearLayout controls=Design.row(activity);panelPlay=previewButton(controls,"Play preview",()->preview.toggle(alarm.tone),true);stop=previewButton(controls,"Stop",preview::stop,false);stop.setContentDescription("Stop preview");panel.addView(controls);previewError=Design.text(panel,"",12,400,0xffa93919);previewError.setPadding(0,Design.dp(activity,6),0,0);body.addView(panel);Design.space(body,8);Design.fixedAction(body,"Use "+(alarm.soundMode.equals(AlarmSoundMode.SINGLE)?AlarmTones.name(alarm.tone):alarm.soundMode.title()),()->{preview.stop();back.run();});update();
    }
    private String toneLabel(String source){return source.equals(alarm.tone)&&source.startsWith("content:")&&!alarm.toneDisplayName.isEmpty()?alarm.toneDisplayName:AlarmTones.name(source);}
    private void toneTabs(LinearLayout body){LinearLayout tabs=Design.row(activity);tabs.setBackground(Design.shape(activity,0xfff5e8dc,14));String[] names={"Built-in","My audio"};for(int n=0;n<names.length;n++){int index=n;FrameLayout hit=new FrameLayout(activity);TextView label=Design.text(activity,names[n],14,tab==n?600:400,Design.INK);label.setGravity(Gravity.CENTER);if(tab==n)label.setBackground(Design.shape(activity,0xfff2decb,12));FrameLayout.LayoutParams copy=new FrameLayout.LayoutParams(-1,Design.dp(activity,40),Gravity.CENTER);copy.setMargins(Design.dp(activity,3),0,Design.dp(activity,3),0);hit.addView(label,copy);hit.setContentDescription(names[n]);SleepPicker.radio(hit,tab==n);hit.setFocusable(true);hit.setOnClickListener(v->{if(index!=tab)InteractionFeedback.selection(v);preview.stop();tab=index;render.run();});tabs.addView(hit,new LinearLayout.LayoutParams(0,Design.dp(activity,48),1));}body.addView(tabs,new LinearLayout.LayoutParams(-1,-2));}
    private String previewSource(){return alarm.soundMode.radio()?"daybreak":alarm.tone;}
    private void radio(LinearLayout body){Design.item(body,"link","Internet radio",AlarmRadioUrl.host(alarm.soundMode.radioUrl),modes);Design.space(body,14);Design.text(body,"Internet required. If the stream cannot play or stalls for 8 sec, Daybreak plays instead. Backup stays bundled.",14,400,Design.MUTED);Design.space(body,18);slider(body,"Alarm volume",alarm.volume,10,100,value->alarm.volume=value,false);Design.space(body,14);LinearLayout panel=Design.col(activity);Design.pad(panel,18,12);panel.setBackground(Design.shape(activity,Design.SOFT,18));Design.text(panel,"Daybreak fallback",18,600,Design.INK);Design.text(panel,"Only the bundled fallback is previewed here.",12,400,Design.MUTED);Design.space(panel,8);slider(panel,"Preview volume",preview.volume(),0,25,preview::volume,true);LinearLayout controls=Design.row(activity);panelPlay=previewButton(controls,"Play preview",()->preview.toggle("daybreak"),true);stop=previewButton(controls,"Stop",preview::stop,false);stop.setContentDescription("Stop preview");panel.addView(controls);previewError=Design.text(panel,"",12,400,0xffa93919);body.addView(panel);Design.space(body,12);Design.fixedAction(body,"Use Internet radio",()->{preview.stop();back.run();});update();}
    private Button previewButton(LinearLayout row,String title,Runnable click,boolean play){Button button=new Button(activity);button.setText(title);button.setAllCaps(false);button.setTextSize(14*Appearance.scale(activity));button.setTypeface(Design.font(activity,600));button.setTextColor(Design.INK);button.setMinHeight(Design.dp(activity,48));button.setMinimumHeight(Design.dp(activity,48));button.setStateListAnimator(null);button.setBackground(Design.touch(activity,play?Design.CREAM:android.graphics.Color.TRANSPARENT,14));button.setOnClickListener(v->click.run());row.addView(button,new LinearLayout.LayoutParams(0,-2,play?3:1));return button;}
    private void slider(LinearLayout parent,String title,int value,int min,int max,java.util.function.IntConsumer change,boolean quiet){
        LinearLayout heading=Design.row(activity);heading.addView(Design.text(activity,title,quiet?13:17,quiet?400:600,quiet?Design.MUTED:Design.INK),new LinearLayout.LayoutParams(0,-2,1));TextView amount=Design.text(activity,activity.getString(R.string.alarm_tone_percent,value),quiet?14:16,600,Design.BROWN);heading.addView(amount,new LinearLayout.LayoutParams(-2,-2));parent.addView(heading,new LinearLayout.LayoutParams(-1,-2));
        LinearLayout rail=Design.row(activity);LinearLayout.LayoutParams low=new LinearLayout.LayoutParams(Design.dp(activity,20),Design.dp(activity,20));low.rightMargin=Design.dp(activity,5);rail.addView(new Design.Icon(activity,"sound",Design.BROWN),low);
        SeekBar seek=new SeekBar(activity);seek.setContentDescription(title);AlarmSliders.style(seek);seek.setMax(max-min);seek.setProgress(Math.max(0,Math.min(max-min,value-min)));rail.addView(seek,new LinearLayout.LayoutParams(0,Design.dp(activity,48),1));LinearLayout.LayoutParams high=new LinearLayout.LayoutParams(Design.dp(activity,24),Design.dp(activity,24));high.leftMargin=Design.dp(activity,5);rail.addView(new Design.Icon(activity,"sound",Design.BROWN),high);parent.addView(rail,new LinearLayout.LayoutParams(-1,Design.dp(activity,48)));
        if(quiet)previewValue=amount;seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int value,boolean user){amount.setText(activity.getString(R.string.alarm_tone_percent,value+min));if(user)change.accept(value+min);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
    }
    private void tone(LinearLayout body,String value){LinearLayout row=Design.row(activity);Design.pad(row,2,8);row.setMinimumHeight(Design.dp(activity,78));LinearLayout choice=Design.row(activity);choice.setMinimumHeight(Design.dp(activity,48));choice.addView(new SleepPicker.Mark(activity,alarm.tone.equals(value)),new LinearLayout.LayoutParams(Design.dp(activity,24),Design.dp(activity,24)));LinearLayout copy=Design.col(activity);copy.setPadding(Design.dp(activity,14),0,Design.dp(activity,4),0);TextView name=Design.text(copy,toneLabel(value),15,600,Design.INK);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);choice.setTooltipText(toneLabel(value));Design.space(copy,5);Design.text(copy,value.equals("daybreak")?"Gentle and natural":value.equals("pulse")?"Steady and clear":value.equals("chime")?"Bright and familiar":value.equals("system")?"Phone’s default alarm":"Audio from your phone",12,400,Design.MUTED);choice.addView(copy,new LinearLayout.LayoutParams(0,-2,1));choice.setContentDescription("Select "+AlarmTones.name(value));if(value.startsWith("content:"))choice.setStateDescription(toneLabel(value));SleepPicker.radio(choice,alarm.tone.equals(value));choice.setFocusable(true);choice.setBackground(Design.touch(activity,android.graphics.Color.TRANSPARENT,12));choice.setOnClickListener(v->{preview.stop();alarm.tone=value;if(!value.startsWith("content:"))alarm.toneDisplayName="";render.run();});row.addView(choice,new LinearLayout.LayoutParams(0,-2,1));if(List.of("daybreak","pulse","chime").contains(value)){FrameLayout host=new FrameLayout(activity);host.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);LinearLayout.LayoutParams waveSpace=new LinearLayout.LayoutParams(Design.dp(activity,82),Design.dp(activity,36));waveSpace.rightMargin=Design.dp(activity,8);row.addView(host,waveSpace);WaveHost pending=new WaveHost(value,host);waveHosts.add(pending);updateWave(pending);}FrameLayout play=new FrameLayout(activity);play.setFocusable(true);play.setOnClickListener(v->preview.toggle(value));row.addView(play,new LinearLayout.LayoutParams(Design.dp(activity,48),Design.dp(activity,48)));buttons.add(new PlayButton(value,play));body.addView(row);}
    void settingsScope(String value){settingsScope=value==null?"":value;}
    boolean optionsShowing(){return dialog!=null&&dialog.isShowing();}
    boolean openSearchOptions(){if(closed||paused||!activity.hasWindowFocus())return false;if(!optionsShowing())options();return true;}
    private void options(){preview.stop();dialog=new Dialog(activity);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=Design.col(activity);Design.pad(panel,22,20);panel.setBackground(Design.shape(activity,Design.CREAM,22));Design.text(panel,"Alarm sound options",22,600,Design.INK);Design.space(panel,14);if(!settingsScope.isEmpty()){Design.text(panel,settingsScope,12,400,Design.MUTED);Design.space(panel,14);}if(modes!=null){Design.item(panel,"sound","Sound playback",alarm.soundMode.title(),()->{dialog.dismiss();modes.run();});Design.line(panel);}Design.toggle(panel,"Extra loud","Use maximum device alarm volume",alarm.extraLoud,on->alarm.extraLoud=on);Design.item(panel,"sun","Gentle wake-up",alarm.rampSeconds==0?"Off":alarm.rampSeconds+" sec",()->{dialog.dismiss();gentle.run();});Design.button(panel,"Done",false,dialog::dismiss);dialog.setContentView(panel);dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(Math.min(activity.getResources().getDisplayMetrics().widthPixels-Design.dp(activity,32),Design.dp(activity,420)),-2);}
    private void update(){if(closed)return;for(PlayButton button:buttons){boolean playing=preview.tone().equals(button.tone)&&(preview.phase()==AlarmTonePreview.Phase.PLAYING||preview.phase()==AlarmTonePreview.Phase.LOADING);button.view.removeAllViews();button.view.addView(new Design.Icon(activity,playing?"pause":"play",playing?Design.CREAM:Design.BROWN),new FrameLayout.LayoutParams(Design.dp(activity,20),Design.dp(activity,20),Gravity.CENTER));button.view.setBackground(Design.touch(activity,playing?Design.BROWN:Design.SOFT,26));button.view.setContentDescription((playing?"Pause ":"Preview ")+AlarmTones.name(button.tone));}if(panelPlay!=null){boolean playing=preview.tone().equals(previewSource())&&(preview.phase()==AlarmTonePreview.Phase.PLAYING||preview.phase()==AlarmTonePreview.Phase.LOADING);String action=playing?"Pause preview":"Play preview";android.text.SpannableString label=new android.text.SpannableString("\uFFFC  "+action);label.setSpan(new android.text.style.ImageSpan(RecordUi.glyph(activity,playing?"pause":"play",Design.INK,14),android.text.style.ImageSpan.ALIGN_BASELINE),0,1,0);panelPlay.setText(label);panelPlay.setContentDescription(action);stop.setVisibility(preview.phase()==AlarmTonePreview.Phase.STOPPED?View.GONE:View.VISIBLE);boolean reveal=!preview.error().isEmpty()&&!preview.error().contentEquals(previewError.getText());previewError.setVisibility(preview.error().isEmpty()?View.GONE:View.VISIBLE);previewError.setText(preview.error());if(reveal){TextView message=previewError;message.post(()->{if(message.isAttachedToWindow())message.requestRectangleOnScreen(new android.graphics.Rect(0,0,message.getWidth(),message.getHeight()),true);});}if(previewValue!=null)previewValue.setText(activity.getString(R.string.alarm_tone_percent,preview.volume()));}}
    private void importAudio(){preview.stop();importError="";try{activity.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),AlarmToneImport.REQUEST);}catch(ActivityNotFoundException|SecurityException failure){importError="Audio files could not be opened. Try again.";render.run();}}
    void result(int result,Intent data){if(closed||activity.isFinishing()||result!=Activity.RESULT_OK)return;Uri uri=data==null?null:data.getData();if(!AlarmToneImport.allowed(uri)){importError="Choose an audio document from Files.";render.run();return;}if(!AlarmToneImport.ACTIVE.compareAndSet(false,true)){importError="Another import is still closing. Try again shortly.";render.run();return;}importing=true;importError="";int request=++importGeneration;CancellationSignal cancel=new CancellationSignal();importingCancel=cancel;AlarmToneImport.Source source=AlarmToneImport.source;int flags=data.getFlags();importTimeout=()->{if(!closed&&request==importGeneration){cancelImport();importError="Audio took too long to open. Choose another file.";render.run();}};main.postDelayed(importTimeout,8000);render.run();worker.execute(()->{AlarmToneImport.Result selected=null;try{selected=source.read(app,uri,flags,cancel);AlarmToneImport.Result outcome=selected;CountDownLatch acknowledged=new CountDownLatch(1);main.post(()->{try{if(closed||request!=importGeneration||cancel.isCanceled())return;main.removeCallbacks(importTimeout);importing=false;importingCancel=null;if(outcome!=null&&outcome.accept()){alarm.tone=outcome.uri;alarm.toneDisplayName=Alarm.cleanToneName(outcome.name);importName=alarm.toneDisplayName.isEmpty()?"My audio":alarm.toneDisplayName;tab=1;}else importError="Audio unavailable. Choose another file.";render.run();}finally{acknowledged.countDown();}});acknowledged.await(8,TimeUnit.SECONDS);}catch(Exception|LinkageError failure){main.post(()->{if(!closed&&request==importGeneration){main.removeCallbacks(importTimeout);importing=false;importingCancel=null;importError="Audio unavailable. Choose another file.";render.run();}});}finally{try{if(selected!=null)selected.discard(app,records,soundPreferences);}finally{AlarmToneImport.ACTIVE.set(false);}}});}
    private void cancelImport(){if(importing){importGeneration++;importing=false;if(importingCancel!=null)try{importingCancel.cancel();}catch(RuntimeException ignored){}importingCancel=null;if(importTimeout!=null)main.removeCallbacks(importTimeout);importError="Import was interrupted. Choose the file again.";}}
    void resume(){boolean refresh=paused;paused=false;preview.visible(true);if(refresh)render.run();}void focus(boolean focused){preview.visible(focused&&!paused);}void pause(){paused=true;preview.visible(false);cancelImport();}void stop(){preview.stop();cancelImport();}
    boolean awaitClosed(long timeout)throws InterruptedException{return worker.awaitTermination(timeout,TimeUnit.MILLISECONDS);}
    boolean assetsReady(){return assetsLoaded;}View captureView(){return dialog!=null&&dialog.isShowing()?dialog.getWindow().getDecorView():activity.getWindow().getDecorView();}
    @Override public void close(){if(closed)return;closed=true;cancelImport();if(dialog!=null)dialog.dismiss();activity.unregisterReceiver(noisy);preview.close();worker.shutdown();}
    private static final class PlayButton {final String tone;final FrameLayout view;PlayButton(String tone,FrameLayout view){this.tone=tone;this.view=view;}}
}
